    async def route_task(self, prompt: str, context: dict = None) -> tuple[CognitiveFaculty, float]:
        """Determine which faculty should handle this task."""
        context_str = json.dumps(context) if context else "{}"

        routing_prompt = f"""Given this task, select the most appropriate cognitive faculty:

Task: {prompt}
Context: {context_str}

Available faculties:
- perception: Pattern recognition
- reasoning: Logical inference
- problem_solving: Multi-step tasks
- generation: Creative output
- {", ".join([f.value for f in CognitiveFaculty][:5])}

Respond with only the faculty name (one word)."""

        try:
            response = await self.client.post(
                f"http://127.0.0.1:13307/v1/chat/completions",
                json={
                    "model": self.ROUTER_MODEL,
                    "messages": [{"role": "user", "content": routing_prompt}],
                    "temperature": 0.1,
                    "max_tokens": 32,
                },
            )

            result = response.json()
            faculty_name = result["choices"][0]["message"]["content"].strip().lower()

            # Map to enum
            faculty_map = {f.value: f for f in CognitiveFaculty}
            faculty = faculty_map.get(faculty_name, CognitiveFaculty.REASONING)
            confidence = 0.8

            return faculty, confidence

        except Exception as e:
            logger.warning(f"Routing failed: {e}, defaulting to reasoning")
            return CognitiveFaculty.REASONING, 0.5

    async def process_task(self, task: CognitiveTask) -> dict[str, Any]:
        """Process a task through the cognitive architecture."""

        # Auto-route if faculty not specified
        if not task.faculty_required:
            faculty, route_conf = await self.route_task(task.prompt, {})
            task.faculty_required = faculty

        primary = self.specialists.get(task.faculty_required)
        if not primary:
            return {"error": f"No specialist for {task.faculty_required}"}

        primary_result = await primary.process(task)

        results = {
            "task_id": task.task_id,
            "routed_to": task.faculty_required.value,
            "primary_result": {
                "output": primary_result.output,
                "confidence": primary_result.confidence,
                "family": primary_result.model_family,
                "latency_ms": primary_result.latency_ms,
            },
        }

        # Secondary faculty if confidence low
        if primary_result.confidence < 0.7 and task.faculty_secondary:
            secondary = self.specialists.get(task.faculty_secondary)
            if secondary:
                sec_result = await secondary.process(
                    task, context={"primary_output": primary_result.output}
                )

                # Choose best result
                if sec_result.confidence > primary_result.confidence:
                    results["final_output"] = sec_result.output
                    results["chosen_faculty"] = task.faculty_secondary.value
                    results["secondary_result"] = {
                        "family": sec_result.model_family,
                        "confidence": sec_result.confidence,
                    }
                else:
                    results["final_output"] = primary_result.output
                    results["chosen_faculty"] = task.faculty_required.value
            else:
                results["final_output"] = primary_result.output
                results["chosen_faculty"] = task.faculty_required.value
        else:
            results["final_output"] = primary_result.output
            results["chosen_faculty"] = task.faculty_required.value

        self.task_history.append(
            {
                "timestamp": datetime.now().isoformat(),
                "task": task.to_dict(),
                "results": results,
            }
        )

        return results

    def evaluate_performance(self) -> CognitiveProfile:
        """Evaluate system performance and update cognitive profile."""

        faculty_scores: dict[CognitiveFaculty, list[float]] = {}

        for entry in self.task_history:
            faculty_name = entry["task"]["faculty_required"]
            faculty = CognitiveFaculty(faculty_name)
            confidence = entry["results"]["primary_result"]["confidence"]

            if faculty not in faculty_scores:
                faculty_scores[faculty] = []
            faculty_scores[faculty].append(confidence)

        for faculty, scores in faculty_scores.items():
            avg_score = sum(scores) / len(scores)
            setattr(self.profile, faculty.value, avg_score)

        return self.profile

    def export_training_datasets(self) -> dict[str, Path]:
        """Export all training data for Unsloth fine-tuning."""
        exported = {}

        for faculty, specialist in self.specialists.items():
            path = specialist.save_training_data()
            if path:
                exported[faculty.value] = path

        return exported

    async def close(self) -> None:
        """Cleanup all specialists."""
        for specialist in self.specialists.values():
            await specialist.close()
        if self.client:
            await self.client.aclose()

    def get_system_stats(self) -> dict[str, Any]:
        """Get comprehensive system statistics."""
        stats = {
            "specialists": {f.value: s.get_stats() for f, s in self.specialists.items()},
            "tasks_processed": len(self.task_history),
            "cognitive_profile": self.profile.to_human_percentile(),
            "agilience_score": self.profile.overall_agilience(),
            "ready_for_training": any(s.training_examples for s in self.specialists.values()),
        }
        return stats


__all__ = [
    "CognitiveFaculty",
    "CognitiveTask",
    "CognitiveProfile",
    "ModelConfig",
    "FacultyResult",
    "FacultySpecialist",
    "MetaCognitiveExecutive",
]

