"""HTTP client for Lemonade server API.

Lazy initialization — no network calls at import time (MCP stdio rule L274).
"""

from __future__ import annotations

import base64
import logging
from pathlib import Path
from typing import Any

import httpx

logger = logging.getLogger(__name__)

_DEFAULT_URL = "http://127.0.0.1:13307"


class LemonadeClient:
    """Sync HTTP client for Lemonade server."""

    def __init__(self, base_url: str = _DEFAULT_URL, timeout: float = 120.0) -> None:
        self._url = base_url
        self._client = httpx.Client(timeout=timeout)

    def health(self) -> dict[str, Any]:
        """GET /api/v1/health — server status and loaded models."""
        return self._client.get(f"{self._url}/api/v1/health").json()

    def stats(self) -> dict[str, Any]:
        """GET /api/v1/stats — inference performance metrics."""
        return self._client.get(f"{self._url}/api/v1/stats").json()

    def system_info(self) -> dict[str, Any]:
        """GET /api/v1/system-info — hardware and backend status."""
        return self._client.get(f"{self._url}/api/v1/system-info").json()

    def list_models(self, show_all: bool = False) -> list[dict[str, Any]]:
        """GET /api/v1/models — list downloaded (or all) models."""
        params = {"show_all": "true"} if show_all else {}
        return self._client.get(f"{self._url}/api/v1/models", params=params).json().get("data", [])

    def pull_model(self, model_name: str, **kwargs: Any) -> dict[str, Any]:
        """POST /api/v1/pull — download a model."""
        payload = {"model_name": model_name, **kwargs}
        return self._client.post(f"{self._url}/api/v1/pull", json=payload).json()

    def load_model(self, model_name: str, **kwargs: Any) -> dict[str, Any]:
        """POST /api/v1/load — load model into memory."""
        payload = {"model_name": model_name, **kwargs}
        return self._client.post(f"{self._url}/api/v1/load", json=payload).json()

    def unload_model(self, model_name: str | None = None) -> dict[str, Any]:
        """POST /api/v1/unload — unload model (or all if None)."""
        payload = {"model_name": model_name} if model_name else {}
        return self._client.post(f"{self._url}/api/v1/unload", json=payload).json()

    def install_backend(self, recipe: str, backend: str) -> dict[str, Any]:
        """POST /api/v1/install — install a backend."""
        return self._client.post(
            f"{self._url}/api/v1/install",
            json={"recipe": recipe, "backend": backend},
        ).json()

    def chat(
        self,
        model: str,
        messages: list[dict[str, str]],
        temperature: float = 0.7,
        max_tokens: int = 512,
    ) -> dict[str, Any]:
        """POST /api/v1/chat/completions — chat inference."""
        return self._client.post(
            f"{self._url}/api/v1/chat/completions",
            json={
                "model": model,
                "messages": messages,
                "temperature": temperature,
                "max_tokens": max_tokens,
            },
        ).json()

    def complete(self, model: str, prompt: str, **kwargs: Any) -> dict[str, Any]:
        """POST /api/v1/completions — text completion."""
        payload = {"model": model, "prompt": prompt, **kwargs}
        return self._client.post(f"{self._url}/api/v1/completions", json=payload).json()

    def embed(self, model: str, texts: list[str]) -> list[list[float]]:
        """POST /api/v1/embeddings — get vector embeddings."""
        resp = self._client.post(
            f"{self._url}/api/v1/embeddings",
            json={"model": model, "input": texts},
        ).json()
        return [d["embedding"] for d in resp.get("data", [])]

    def rerank(self, model: str, query: str, documents: list[str]) -> list[dict[str, Any]]:
        """POST /api/v1/reranking — rerank documents by relevance."""
        resp = self._client.post(
            f"{self._url}/api/v1/reranking",
            json={"model": model, "query": query, "documents": documents},
        ).json()
        return resp.get("results", [])

    def generate_image(
        self,
        model: str,
        prompt: str,
        size: str = "512x512",
        steps: int = 20,
        cfg_scale: float = 7.0,
    ) -> str:
        """POST /api/v1/images/generations — returns base64 PNG."""
        resp = self._client.post(
            f"{self._url}/api/v1/images/generations",
            json={
                "model": model,
                "prompt": prompt,
                "size": size,
                "steps": steps,
                "cfg_scale": cfg_scale,
            },
            timeout=300.0,
        ).json()
        return resp["data"][0]["b64_json"]

    def speak(
        self,
        text: str,
        model: str = "kokoro-v1",
        voice: str = "af_heart",
        response_format: str = "wav",
    ) -> bytes:
        """POST /api/v1/audio/speech — TTS, returns audio bytes."""
        resp = self._client.post(
            f"{self._url}/api/v1/audio/speech",
            json={
                "model": model,
                "input": text,
                "voice": voice,
                "response_format": response_format,
            },
            timeout=60.0,
        )
        return resp.content

