"""Tests for KnowledgeOracle unified cross-store search."""

from __future__ import annotations

from pathlib import Path
from unittest.mock import MagicMock, patch

import pytest

from cohezion.compound.knowledge_oracle import KnowledgeOracle, OracleResponse, OracleResult


@pytest.fixture
def oracle_with_vault(tmp_path: Path) -> KnowledgeOracle:
    """Create an oracle with a temp vault and fake learnings file."""
    vault = tmp_path / "vault"
    (vault / "decisions").mkdir(parents=True)
    (vault / "patterns").mkdir(parents=True)

    # Create test vault notes
    (vault / "decisions" / "test-decision.md").write_text(
        "---\ntitle: Lemonade Architecture\n---\nDecision about Lemonade local inference.\n"
    )
    (vault / "patterns" / "test-pattern.md").write_text(
        "---\ntitle: HIHO Stability Pattern\n---\nPattern for HIHO stability monitoring.\n"
    )

    # Create test KEY_LEARNINGS
    learnings = tmp_path / "KEY_LEARNINGS.md"
    learnings.write_text(
        "L346: Dual-port Lemonade architecture for local inference.\n"
        "L347: Qwen3 requires /no_think prefix.\n"
        "L100: Unrelated learning about Rust FFI.\n"
    )

    return KnowledgeOracle(
        vault_path=vault,
        learnings_path=learnings,
        surrealdb_url="http://127.0.0.1:99999",  # Unreachable — tests SurrealDB fallback
    )


@pytest.mark.unit
class TestOracleSearch:
    """Core search functionality."""

    def test_ask_returns_results_from_vault_and_learnings(
        self, oracle_with_vault: KnowledgeOracle,
    ) -> None:
        response = oracle_with_vault.ask("Lemonade")
        assert response.sources_queried >= 2  # vault + learnings (SurrealDB may fail)
        assert response.total_matches > 0
        sources = {r.source for r in response.results}
        assert "vault" in sources or "learnings" in sources

    def test_ask_deduplicates_by_path(self, oracle_with_vault: KnowledgeOracle) -> None:
        response = oracle_with_vault.ask("Lemonade")
        paths = [r.path for r in response.results]
        assert len(paths) == len(set(paths))

    def test_learnings_search_finds_L_entries(
        self, oracle_with_vault: KnowledgeOracle,
    ) -> None:
        response = oracle_with_vault.ask("Lemonade")
        learning_results = [r for r in response.results if r.source == "learnings"]
        assert len(learning_results) > 0
        assert any("L346" in r.title or "L346" in r.content for r in learning_results)

    def test_empty_query_returns_empty(self, oracle_with_vault: KnowledgeOracle) -> None:
        response = oracle_with_vault.ask("")
        assert response.total_matches == 0
        assert response.results == []

    def test_no_matches_returns_empty_results(
        self, oracle_with_vault: KnowledgeOracle,
    ) -> None:
        response = oracle_with_vault.ask("xyznonexistent12345")
        assert response.total_matches == 0

    def test_results_sorted_by_relevance(self, oracle_with_vault: KnowledgeOracle) -> None:
        response = oracle_with_vault.ask("HIHO stability")
        if len(response.results) > 1:
            for i in range(len(response.results) - 1):
                assert response.results[i].relevance >= response.results[i + 1].relevance


@pytest.mark.unit
class TestSurrealDBFallback:
    """Graceful handling when SurrealDB is unreachable."""

    def test_surrealdb_failure_still_returns_vault_results(
        self, oracle_with_vault: KnowledgeOracle,
    ) -> None:
        # SurrealDB URL is unreachable, but vault + learnings should still work
        response = oracle_with_vault.ask("Lemonade")
        assert response.total_matches > 0
        assert response.sources_queried >= 2


@pytest.mark.unit
class TestOracleResult:
    """Data class behavior."""

    def test_oracle_result_is_frozen(self) -> None:
        r = OracleResult(
            source="vault",
            title="Test",
            content="Content",
            path="test.md",
            relevance=0.8,
        )
        with pytest.raises(AttributeError):
            r.source = "other"

    def test_oracle_response_fields(self) -> None:
        resp = OracleResponse(question="test", sources_queried=3, total_matches=10)
        assert resp.question == "test"
        assert resp.results == []

